import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext.jsx';
import OutlineIcon from '../icons/OutlineIcon.jsx';
import './HeroHome.css';

const HERO_PILLS = [
  { to: '/career-assessment', label: 'Assessment', icon: 'compass', tone: 'amber' },
  { to: '/kcet-predictor', label: 'KCET', icon: 'cap', tone: 'blue' },
  { to: '/pgcet-predictor', label: 'PGCET', icon: 'book', tone: 'green' },
  { to: '/college-compare', label: 'Compare', icon: 'scale', tone: 'lilac' },
  { to: '/college-admission-enquiry', label: 'Admission', icon: 'handshake', tone: 'sky' },
];

export default function HeroHome() {
  const [email, setEmail] = useState('');
  const navigate = useNavigate();
  const { student } = useAuth();

  const submitEmail = (e) => {
    e.preventDefault();
    if (student) {
      navigate('/dashboard');
      return;
    }
    const next = email.trim()
      ? `/register?email=${encodeURIComponent(email.trim())}`
      : '/register';
    navigate(next);
  };

  return (
    <section className="mmc-hero" aria-label="Map your career path">
      <div className="container mmc-hero-grid">
        <div className="mmc-hero-copy">
          <p className="mmc-hero-stats">1,000+ Students guided · 150+ Colleges · 24/7 Support</p>
          <h1>Map Your Career Path</h1>
          <p className="mmc-hero-sub">
            Assessments, KCET & PGCET predictors, and admission support — in one place.
          </p>

          {student ? (
            <div className="mmc-hero-actions">
              <Link to="/dashboard" className="btn btn-ink">
                Open dashboard
                <OutlineIcon name="arrow" size={16} />
              </Link>
              <Link to="/career-assessment" className="btn btn-outline">
                Take assessment
              </Link>
            </div>
          ) : (
            <form className="mmc-hero-signup" onSubmit={submitEmail}>
              <label className="sr-only" htmlFor="mmc-hero-email">Email</label>
              <input
                id="mmc-hero-email"
                type="email"
                name="email"
                placeholder="Enter your email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                autoComplete="email"
              />
              <button type="submit" className="btn btn-ink">
                Sign up for free
                <OutlineIcon name="arrow" size={16} />
              </button>
            </form>
          )}
        </div>

        <div className="mmc-hero-visual">
          <div className="mmc-hero-stage">
            <span className="mmc-hero-blob mmc-hero-blob--ink" aria-hidden="true" />
            <span className="mmc-hero-blob mmc-hero-blob--lime" aria-hidden="true" />
            <span className="mmc-hero-blob mmc-hero-blob--yellow" aria-hidden="true" />
            <img
              src="/images/hero-student-cutout.png"
              alt="Student exploring colleges on her phone"
              className="mmc-hero-cutout"
              fetchPriority="high"
              decoding="async"
            />
          </div>

          <div className="mmc-hero-tags">
            <Link to="/career-assessment" className="mmc-hero-tag mmc-hero-tag--yellow">Career Assessment</Link>
            <Link to="/kcet-predictor" className="mmc-hero-tag">KCET Predictor</Link>
            <Link to="/pgcet-predictor" className="mmc-hero-tag">PGCET Predictor</Link>
            <Link to="/college-compare" className="mmc-hero-tag">College Compare</Link>
          </div>

          <article className="mmc-hero-info">
            <span className="mmc-hero-info-icon">
              <OutlineIcon name="people" size={18} />
            </span>
            <strong>Interactive guidance</strong>
            <p>Counselling that turns assessment results into a college shortlist and a clear next step.</p>
          </article>
        </div>
      </div>

      <div className="container mmc-hero-pills">
        {HERO_PILLS.map((pill) => (
          <Link key={pill.to} to={pill.to} className={`mmc-hero-pill mmc-hero-pill--${pill.tone}`}>
            <span className="mmc-hero-pill-icon">
              <OutlineIcon name={pill.icon} size={18} />
            </span>
            <span>{pill.label}</span>
          </Link>
        ))}
      </div>
    </section>
  );
}
